      const boundaries = rates.label === 'Normal' ? [{label: 'Flat', at: 0.5, direction: 'down'}]
        : rates.label === 'Flat' ? [{label: 'Normal', at: 0.5, direction: 'up'}, {label: 'Inverted', at: 0, direction: 'down'}]
